create_ambient_object = { type = <key> location = <target> }
For VFX use:
create_ambient_object = {
	type = <key>
	scale = <float>
	location = <target>
	use_3d_location = <bool, use 3D entity or 2D coordinate of the location entity as base>
	entity_offset = {
		min = <int>
		max = <int>
	}
	entity_offset_angle = {
		min = <int>
		max = <int>
	}
	entity_offset_height = {
		min = <int>
		max = <int>
	}
	entity_face_object = star/FROM/etc
	entity_scale_to_size = yes/no
	play_animation_once = yes/no
	target = <target>
	duration = <int, days>
	is_wreck = yes/no
}

create_balanced_fleet = {
	name = <string>
	size = <int>
	can_overflow = yes/no # default yes
	ship_designs = { NAME_a NAME_b } # optional; if omitted, uses the country's own designs
	effect = { <set_location etc effects go here> }
}

create_cluster = {
	id = <some_id>
	center = <system, spatial object>
	radius = 30
}

create_colony = {
	owner = <target>
	species = <target / key>
	ethos = <random / target / { ethic = <key> ethic = <key> }>
}

create_country = {
	name = <string / random / <target>>
	adjective = <string / <target>>
	ruler = <string / random>
	contact_rule = <always / never / on_action_only / does_first_contact_sites / auto>
	day_zero_contact = yes/no
	exclude_day_zero_contact = <target>
	type = <key>
	auto_delete = yes/no
	name_list = <key / <target>>
	ship_prefix = <string>
	default_ships = yes/no
	authority = <key / <target>>
	civics = random / <target> / { civic = <key> civic = random }
	randomize_ethos = yes/no
	ethos = random / <target> / { ethic = <key> }
	species = last_created / random / <string> / <target>
	set_capital_from_species = yes/no
	ignore_initial_colony_error = yes/no
	flag = random / none / <target> / {
		icon = { category = <key> file = <filename.dds> }
		background = { category = <key> file = <filename.dds> }
		# Four color swatches (keys from flags/colors.txt). Slots: 0=primary (red), 1=secondary (green), 2=tertiary (blue), 3=ship color (alpha, shader-inert). Use null for unused slots.
		colors = { <key> <key> <key> <key> }
		use_ship_color = yes/no # default no
		# When yes, slot 3 swatch ship= value is used for ships Slot 3 must be a real swatch.	}
	origin = <target>
	graphical_culture = <key>
	city_graphical_culture = <key>
	ship_kinds = { <ship_category_keys> }
	room = <key>
	nomadic = yes/no/<target> # default: no
	released_by_country = <target> # grants communications from this country and its contacts
	released_from_country = <target> # copies techs, designs, traditions, survey data; creates truce
	use_hostilities_from = <target>
	government_restrictions = { <see common/governments/readme_requirements.txt> }
	remove_invalid_civics = yes/no # default: no
	effect = { <effects executed on country scope> }
}

create_espionage_asset = {
	type = <espionage asset type>
	effect = { <effects executed on asset> }
}

create_message = {
  type = BYPASS_EXPLORED
  localization = BYPASS_EXPLORED_MESSAGE
  days = 30 (-1 is infinite)
  target = root
  variable = { type = name localization = SYSTEM1 scope = from }
  variable = { type = name localization = SYSTEM2 scope = fromfrom }
}

create_nebula = {
	name = <name> (loc synced, optional - default is random)
	radius = 100
	effect = { <effects on every system in the new nebula> }
}

create_random_fleet = {
	name = <string>
	size = <int>
	can_overflow = yes/no # default yes
	ship_designs = { # optional; if omitted, uses the country's own designs at uniform weight
		NAME_a # bare name, weight 1, no min/max
		{ design = NAME_b weight = 2.4 min = 1 max = 3 }
	}
	effect = { <set_location etc effects go here> }
}

create_rebels = {
	name = <random / string>
	authority = <random / key>
	civics = random / { civic = <key> civic = random }
	species = <target>
	ethos = <random / { ethic = <key> ethic = <key> }
}

create_starbase = {
	owner = <target>
	size = <ship_size>
	design=<starbase global design>s
	module = <starbase_module>
	building = <starbase_building>
	effect = { ... }
}

damage_ship = 120
